/*
 * KingSight host bridge for the MMG dashboard (public/cmhc/mmg-dashboard.html, generated by
 * tools/cmhc/build-v7-host.mjs). Hand-written; loaded before the report's own code.
 *
 * The report runs unchanged inside an iframe on the CMHC Dashboard page. The page (window.parent.__cmhcHost,
 * see cmhc-host.service.ts) supplies:
 *   pipeline   live DealPath rows, already filtered on the server to the loans this user may see (ACC-08)
 *   storage    where the report's localStorage goes: team settings are saved to the API (Admins / Reviewers
 *              only), loan-sized data stays in memory, view preferences stay in this browser
 *   viewer     { name, lockUw, lockOrig } — the user's linked name, and whether the Underwriter / Originator
 *              person picker is locked to it (ACC-02, ACC-07)
 *   navigate   called when the report switches tab, so the URL and role access stay in KingSight's hands
 *   view       the tab KingSight is currently showing
 */
(function () {
  'use strict';

  var host = null;
  try {
    host = window.parent !== window ? window.parent.__cmhcHost || null : null;
  } catch (e) {
    host = null;
  }
  window.__cmhcHost = host;

  /* The file's saved settings (team configuration only) are the starting values under anything saved since. */
  var fileState = null;
  try {
    fileState = JSON.parse((document.getElementById('file-state').textContent || '').trim() || 'null');
  } catch (e) {
    fileState = null;
  }
  window.FILE_STATE = fileState;
  var seed = (fileState && fileState.settings) || {};
  var removed = {};
  var memory = {};
  var has = Object.prototype.hasOwnProperty;

  var store = {
    getItem: function (k) {
      k = String(k);
      var v = host ? host.storage.getItem(k) : has.call(memory, k) ? memory[k] : null;
      if (v != null) return v;
      if (removed[k]) return null;
      return has.call(seed, k) ? seed[k] : null;
    },
    setItem: function (k, v) {
      k = String(k);
      v = String(v);
      delete removed[k];
      if (host) host.storage.setItem(k, v);
      else memory[k] = v;
    },
    removeItem: function (k) {
      k = String(k);
      removed[k] = true;
      if (host) host.storage.removeItem(k);
      else delete memory[k];
    },
    key: function () {
      return null;
    },
    clear: function () {},
    get length() {
      return 0;
    },
  };
  try {
    Object.defineProperty(window, 'localStorage', { configurable: true, get: function () { return store; } });
  } catch (e) {
    /* falls back to the browser's own storage */
  }
  // Nothing is ever restored from the report's own session cache: the live pipeline is the only dataset.
  try {
    Object.defineProperty(window, 'sessionStorage', {
      configurable: true,
      get: function () {
        return { getItem: function () { return null; }, setItem: function () {}, removeItem: function () {} };
      },
    });
  } catch (e) {
    /* ignore */
  }

  /* The report asks "who is viewing?" to open the Underwriter / Reviewer dashboards on the viewer's own page. */
  var viewerName = host && host.viewer && host.viewer.name ? String(host.viewer.name) : '';
  window.claude = {
    use: function (what) {
      return what === 'user' ? { me: function () { return viewerName ? { name: viewerName } : null; } } : null;
    },
  };

  // The standalone file's "your changes stay in this browser" notice does not apply here.
  window.closePrivateNotice = function () {
    var ov = document.getElementById('private-ov');
    if (ov) ov.classList.remove('open');
  };

  /** Runs after the report's own code (and its boot) — loads the live pipeline the same way an upload does. */
  window.__cmhcHostStart = function () {
    var body = document.body;
    if (!host) {
      body.classList.add('cmhc-standalone');
      body.insertAdjacentHTML(
        'afterbegin',
        '<div class="cmhc-host-msg">Open the MMG Dashboard from KingSight (CMHC Dashboard).</div>',
      );
      return;
    }
    /* The API sends dates as plain yyyy-MM-dd. The report's toISO() runs them through new Date(), which reads
       them as UTC midnight — the previous evening in Toronto — so every date (Funding Date included) came out
       a day early. Plain dates are kept as they are; anything else still goes through the report's own parser. */
    var reportToISO = window.toISO;
    if (typeof reportToISO === 'function') {
      window.toISO = function (v) {
        var iso = /^(\d{4}-\d{2}-\d{2})(T00:00(:00(\.0+)?)?)?$/.exec(v == null ? '' : String(v).trim());
        return iso ? iso[1] : reportToISO(v);
      };
    }

    if (host.viewer && host.viewer.lockUw) body.classList.add('cmhc-lock-uw');
    if (host.viewer && host.viewer.lockOrig) body.classList.add('cmhc-lock-orig');

    /* Tab switches from inside the report (links, buttons) go through KingSight's router and role check.
       The first render (the report always opens Overview) shows the tab KingSight is on instead. */
    var show = window.setView;
    var booting = true;
    window.__cmhcShow = function (v) {
      var t = { underwriters: 'uw', reviewers: 'rev' }[v];
      if (t && typeof window.wuDefaults === 'function') window.wuDefaults(t);
      show(v);
    };
    window.setView = function (v) {
      if (booting) {
        show(host.view() || v);
        return;
      }
      host.navigate(v);
    };

    try {
      var p = host.pipeline;
      var map = window.autoMap(p.columns);
      var nameIdx = map.name;
      var links = (p.links || []).map(function (l) {
        if (!l) return null;
        var o = {};
        o[nameIdx] = l;
        return o;
      });
      window.PARSED = {
        headers: p.columns,
        rows: p.rows,
        links: links,
        created: null,
        dataAt: p.generatedAt || null,
        dataAtSrc: p.generatedAt ? 'export' : null,
      };
      window.MAP = map;
      window.FILE_NAME = 'KingSight live pipeline';
      var ai = document.getElementById('asof-input');
      if (ai) ai.value = p.asOf;

      // A live dashboard reloads all day; the report's "this date was already recorded" notice is for uploads.
      var hist = window.HIST;
      var sameDay = !!(hist && hist.snapshots && hist.snapshots.some(function (s) { return s.asOf === p.asOf; }));
      var ok = window.buildFromMapping();
      if (sameDay) window.HIST_NOTICE = '';
      booting = false;
      if (!ok) {
        host.failed('The live pipeline is missing columns the dashboard needs.');
        return;
      }
      body.classList.add('cmhc-ready');
      window.__cmhcShow(host.view() || 'overview');
      host.ready(window);
    } catch (e) {
      booting = false;
      console.error(e);
      host.failed('The dashboard could not be built from the live pipeline.');
    }
  };
})();
